mapper.update:
UPDATE ai_conversation SET transcript_json = CAST(#{transcriptJson} AS JSON),
processing_status = 'PROCESSING',
processing_started_at = #{processingStartedAt},
last_message_at = #{processingStartedAt},
version = version + 1
WHERE ai_conversation_id = #{aiConversationId}
AND user_id = #{userId}
AND status = 'ACTIVE'
AND processing_status = 'IDLE'
AND version = #{version}

UPDATE ai_conversation SET transcript_json = CAST(#{transcriptJson} AS JSON),
processing_status = 'IDLE',
processing_started_at = NULL,
last_message_at = #{failedAt},
version = version + 1
WHERE ai_conversation_id = #{aiConversationId}
AND user_id = #{userId}
AND processing_status = 'PROCESSING'
AND version = #{version}
